/**
 * Data for the scan showcase on the preview screen.
 *
 * Generated by `npm run showcase -- <photo.jpg>`, which runs a REAL YouCam skin analysis on
 * the photo and saves YouCam's own detection masks and scores into /public/showcase.
 * Until that has been run, SHOWCASE is null and the screen uses an illustration.
 */
export type Showcase = {
  /** Resized photo returned by YouCam; the masks line up with it exactly. */
  image: string;
  /** YouCam detection masks (transparent PNGs), keyed by concern. */
  masks: Partial<Record<"age_spot" | "acne" | "texture", string>>;
  /** raw_score per concern, 1-100, higher = clearer. */
  scores: Record<string, number>;
  skinType?: string;
  /** Shown in the UI, e.g. "AI-generated portrait". */
  credit: string;
  analyzedAt: string;
};

export const SHOWCASE: Showcase | null = null;
